/// <summary>
/// CB129 Cancellation of Open SO/PO lines
/// </summary>
internal final class METSalesCancelController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>Constuct new object</summary>
/// <param name = "_args">Arguments</param>
/// <param name = "_executionMode">Execution mode</param>
/// <returns>New Controller Object</returns>
public static METSalesCancelController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METSalesCancelController controller = new METSalesCancelController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

/// <summary>
/// New method specifying the service class method to call
/// </summary>
protected void new()
{
    super(classstr(METSalesCancelService), methodstr(METSalesCancelService, processOperation), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// The caption method of the batch job dialog.
/// </summary>
/// <returns>String value to be used on dialog</returns>
public ClassDescription caption()
{
    return "@MET:CancelSOLines";
}

/// <summary>
/// The main method of the batch job.
/// </summary>
/// <param name = "_args">The arguments passed by the caller object.</param>
public static void main(Args _args)
{
    FormRun                 caller;
    MultiSelectionHelper    helper;
    SalesLine               salesLine;
    SysOperationController  controller = METSalesCancelController::construct(_args);
    container               conSalesLine;
    METSalesCancelContract  contract;

    boolean confirmCancel = Box::okCancel("@MET:CancelWarning",DialogButton::Cancel);

    if (confirmCancel)
    {
        caller      = _args.caller();
        helper      = MultiSelectionHelper::createFromCaller(caller);
        salesLine   = helper.getFirst();

        while (salesLine)
        {
            conSalesLine += salesLine.RecId;
            salesLine = helper.getNext();
        }

        contract = controller.getDataContractObject() as METSalesCancelContract;
        contract.parmSalesLineRecords(conSalesLine);
        controller.startOperation();
    }
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}
